00047 AdaptiveLoopFilter::AdaptiveLoopFilter()
00048   : m_classifier( nullptr )
00049 {
00050   for (size_t i = 0; i < NUM_DIRECTIONS; i++)
00051   {
00052     m_laplacian[i] = m_laplacianPtr[i];
00053     for (size_t j = 0; j < sizeof(m_laplacianPtr[i]) / sizeof(m_laplacianPtr[i][0]); j++)
00054     {
00055       m_laplacianPtr[i][j] = m_laplacianData[i][j];
00056     }
00057   }
00058 
00059   for( int compIdx = 0; compIdx < MAX_NUM_COMPONENT; compIdx++ )
00060   {
00061     m_ctuEnableFlag[compIdx] = nullptr;
00062     m_ctuAlternative[compIdx] = nullptr;
00063   }
00064 
00065   m_deriveClassificationBlk = deriveClassificationBlk;
00066   m_filterCcAlf = filterBlkCcAlf<CC_ALF>;
00067   m_filter5x5Blk = filterBlk<ALF_FILTER_5>;
00068   m_filter7x7Blk = filterBlk<ALF_FILTER_7>;
00069 
00070 #if ENABLE_SIMD_OPT_ALF
00071 #ifdef TARGET_SIMD_X86
00072   initAdaptiveLoopFilterX86();
00073 #endif
00074 #endif
00075 }
00076 
00077 bool AdaptiveLoopFilter::isCrossedByVirtualBoundaries( const CodingStructure& cs, const int xPos, const int yPos, const int width, const int height, bool& clipTop, bool& clipBottom, bool& clipLeft, bool& clipRight, int& numHorVirBndry, int& numVerVirBndry, int horVirBndryPos[], int verVirBndryPos[], int& rasterSliceAlfPad )
00078 {
00079   clipTop = false; clipBottom = false; clipLeft = false; clipRight = false;
00080   numHorVirBndry = 0; numVerVirBndry = 0;
00081   const PPS*   pps = cs.pps;
00082   const PicHeader* picHeader = cs.picHeader;
00083 
00084   if( picHeader->getVirtualBoundariesPresentFlag() )
00085   {
00086     for( int i = 0; i < picHeader->getNumHorVirtualBoundaries(); i++ )
00087     {
00088       if( picHeader->getVirtualBoundariesPosY(i) == yPos )
00089       {
00090         clipTop = true;
00091       }
00092       else if( picHeader->getVirtualBoundariesPosY(i) == yPos + height )
00093       {
00094         clipBottom = true;
00095       }
00096       else if( yPos < picHeader->getVirtualBoundariesPosY(i) && picHeader->getVirtualBoundariesPosY(i) < yPos + height )
00097       {
00098         horVirBndryPos[numHorVirBndry++] = picHeader->getVirtualBoundariesPosY(i);
00099       }
00100     }
00101     for( int i = 0; i < picHeader->getNumVerVirtualBoundaries(); i++ )
00102     {
00103       if( picHeader->getVirtualBoundariesPosX(i) == xPos )
00104       {
00105         clipLeft = true;
00106       }
00107       else if( picHeader->getVirtualBoundariesPosX(i) == xPos + width )
00108       {
00109         clipRight = true;
00110       }
00111       else if( xPos < picHeader->getVirtualBoundariesPosX(i) && picHeader->getVirtualBoundariesPosX(i) < xPos + width )
00112       {
00113         verVirBndryPos[numVerVirBndry++] = picHeader->getVirtualBoundariesPosX(i);
00114       }
00115     }
00116   }
00117 
00118   const Slice& slice = *(cs.slice);
00119   int   ctuSize = slice.getSPS()->getCTUSize();
00120   const Position currCtuPos(xPos, yPos);
00121   const CodingUnit *currCtu = cs.getCU(currCtuPos, CHANNEL_TYPE_LUMA);
00122   const SubPic& curSubPic = slice.getPPS()->getSubPicFromPos(currCtuPos);
00123   bool loopFilterAcrossSubPicEnabledFlag = curSubPic.getloopFilterAcrossEnabledFlag();
00124   //top
00125   if (yPos >= ctuSize && clipTop == false)
00126   {
00127     const Position prevCtuPos(xPos, yPos - ctuSize);
00128     const CodingUnit *prevCtu = cs.getCU(prevCtuPos, CHANNEL_TYPE_LUMA);
00129     if ((!pps->getLoopFilterAcrossSlicesEnabledFlag() && !CU::isSameSlice(*currCtu, *prevCtu)) ||
00130         (!pps->getLoopFilterAcrossTilesEnabledFlag()  && !CU::isSameTile(*currCtu,  *prevCtu))
00131       || (!loopFilterAcrossSubPicEnabledFlag && !CU::isSameSubPic(*currCtu, *prevCtu))
00132       )
00133     {
00134       clipTop = true;
00135     }
00136   }
00137 
00138   //bottom
00139   if (yPos + ctuSize < cs.pcv->lumaHeight && clipBottom == false)
00140   {
00141     const Position nextCtuPos(xPos, yPos + ctuSize);
00142     const CodingUnit *nextCtu = cs.getCU(nextCtuPos, CHANNEL_TYPE_LUMA);
00143     if ((!pps->getLoopFilterAcrossSlicesEnabledFlag() && !CU::isSameSlice(*currCtu, *nextCtu)) ||
00144         (!pps->getLoopFilterAcrossTilesEnabledFlag()  && !CU::isSameTile(*currCtu,  *nextCtu))
00145       || (!loopFilterAcrossSubPicEnabledFlag && !CU::isSameSubPic(*currCtu, *nextCtu))
00146       )
00147     {
00148       clipBottom = true;
00149     }
00150   }
00151 
00152   //left
00153   if (xPos >= ctuSize && clipLeft == false)
00154   {
00155     const Position prevCtuPos(xPos - ctuSize, yPos);
00156     const CodingUnit *prevCtu = cs.getCU(prevCtuPos, CHANNEL_TYPE_LUMA);
00157     if ((!pps->getLoopFilterAcrossSlicesEnabledFlag() && !CU::isSameSlice(*currCtu, *prevCtu)) ||
00158         (!pps->getLoopFilterAcrossTilesEnabledFlag()  && !CU::isSameTile(*currCtu,  *prevCtu))
00159       || (!loopFilterAcrossSubPicEnabledFlag && !CU::isSameSubPic(*currCtu, *prevCtu))
00160       )
00161     {
00162       clipLeft = true;
00163     }
00164   }
00165 
00166   //right
00167   if (xPos + ctuSize < cs.pcv->lumaWidth && clipRight == false)
00168   {
00169     const Position nextCtuPos(xPos + ctuSize, yPos);
00170     const CodingUnit *nextCtu = cs.getCU(nextCtuPos, CHANNEL_TYPE_LUMA);
00171     if ((!pps->getLoopFilterAcrossSlicesEnabledFlag() && !CU::isSameSlice(*currCtu, *nextCtu)) ||
00172         (!pps->getLoopFilterAcrossTilesEnabledFlag()  && !CU::isSameTile(*currCtu,  *nextCtu))
00173       || (!loopFilterAcrossSubPicEnabledFlag && !CU::isSameSubPic(*currCtu, *nextCtu))
00174       )
00175     {
00176       clipRight = true;
00177     }
00178   }
00179 
00180   rasterSliceAlfPad = 0;
00181   if ( !clipTop && !clipLeft )
00182   {
00183     //top-left CTU
00184     if ( xPos >= ctuSize && yPos >= ctuSize )
00185     {
00186       const Position prevCtuPos( xPos - ctuSize, yPos - ctuSize );
00187       const CodingUnit *prevCtu = cs.getCU( prevCtuPos, CHANNEL_TYPE_LUMA );
00188       if ( !pps->getLoopFilterAcrossSlicesEnabledFlag() && !CU::isSameSlice( *currCtu, *prevCtu ) )
00189       {
00190         rasterSliceAlfPad = 1;
00191       }
00192     }
00193   }
00194 
00195   if ( !clipBottom && !clipRight )
00196   {
00197     //bottom-right CTU
00198     if ( xPos + ctuSize < cs.pcv->lumaWidth && yPos + ctuSize < cs.pcv->lumaHeight )
00199     {
00200       const Position nextCtuPos( xPos + ctuSize, yPos + ctuSize );
00201       const CodingUnit *nextCtu = cs.getCU( nextCtuPos, CHANNEL_TYPE_LUMA );
00202       if ( !pps->getLoopFilterAcrossSlicesEnabledFlag() && !CU::isSameSlice( *currCtu, *nextCtu ) )
00203       {
00204         rasterSliceAlfPad += 2;
00205       }
00206     }
00207   }
00208 
00209   return numHorVirBndry > 0 || numVerVirBndry > 0 || clipTop || clipBottom || clipLeft || clipRight || rasterSliceAlfPad;
00210 }
