00300 void AdaptiveLoopFilter::applyCcAlfFilter(CodingStructure &cs, ComponentID compID, const PelBuf &dstBuf,
00301                                           const PelUnitBuf &recYuvExt, uint8_t *filterControl,
00302                                           const short filterSet[MAX_NUM_CC_ALF_FILTERS][MAX_NUM_CC_ALF_CHROMA_COEFF],
00303                                           const int   selectedFilterIdx)
00304 {
00305   bool clipTop = false, clipBottom = false, clipLeft = false, clipRight = false;
00306   int  numHorVirBndry = 0, numVerVirBndry = 0;
00307   int  horVirBndryPos[] = { 0, 0, 0 };
00308   int  verVirBndryPos[] = { 0, 0, 0 };
00309 
00310   int ctuIdx = 0;
00311   for( int yPos = 0; yPos < m_picHeight; yPos += m_maxCUHeight )
00312   {
00313     for( int xPos = 0; xPos < m_picWidth; xPos += m_maxCUWidth )
00314     {
00315       int filterIdx =
00316         (filterControl == nullptr)
00317           ? selectedFilterIdx
00318           : filterControl[(yPos >> cs.pcv->maxCUHeightLog2) * cs.pcv->widthInCtus + (xPos >> cs.pcv->maxCUWidthLog2)];
00319       bool skipFiltering = (filterControl != nullptr && filterIdx == 0) ? true : false;
00320       if (!skipFiltering)
00321       {
00322         if (filterControl != nullptr)
00323         {
00324           filterIdx--;
00325         }
00326 
00327         const int16_t *filterCoeff = filterSet[filterIdx];
00328 
00329         const int width        = (xPos + m_maxCUWidth > m_picWidth) ? (m_picWidth - xPos) : m_maxCUWidth;
00330         const int height       = (yPos + m_maxCUHeight > m_picHeight) ? (m_picHeight - yPos) : m_maxCUHeight;
00331         const int chromaScaleX = getComponentScaleX(compID, m_chromaFormat);
00332         const int chromaScaleY = getComponentScaleY(compID, m_chromaFormat);
00333 
00334         int rasterSliceAlfPad = 0;
00335         if (isCrossedByVirtualBoundaries(cs, xPos, yPos, width, height, clipTop, clipBottom, clipLeft, clipRight,
00336                                          numHorVirBndry, numVerVirBndry, horVirBndryPos, verVirBndryPos,
00337                                          rasterSliceAlfPad))
00338         {
00339           int yStart = yPos;
00340           for (int i = 0; i <= numHorVirBndry; i++)
00341           {
00342             const int  yEnd   = i == numHorVirBndry ? yPos + height : horVirBndryPos[i];
00343             const int  h      = yEnd - yStart;
00344             const bool clipT  = (i == 0 && clipTop) || (i > 0) || (yStart == 0);
00345             const bool clipB  = (i == numHorVirBndry && clipBottom) || (i < numHorVirBndry) || (yEnd == m_picHeight);
00346             int        xStart = xPos;
00347             for (int j = 0; j <= numVerVirBndry; j++)
00348             {
00349               const int  xEnd  = j == numVerVirBndry ? xPos + width : verVirBndryPos[j];
00350               const int  w     = xEnd - xStart;
00351               const bool clipL = (j == 0 && clipLeft) || (j > 0) || (xStart == 0);
00352               const bool clipR = (j == numVerVirBndry && clipRight) || (j < numVerVirBndry) || (xEnd == m_picWidth);
00353               const int  wBuf  = w + (clipL ? 0 : MAX_ALF_PADDING_SIZE) + (clipR ? 0 : MAX_ALF_PADDING_SIZE);
00354               const int  hBuf  = h + (clipT ? 0 : MAX_ALF_PADDING_SIZE) + (clipB ? 0 : MAX_ALF_PADDING_SIZE);
00355               PelUnitBuf buf   = m_tempBuf2.subBuf(UnitArea(cs.area.chromaFormat, Area(0, 0, wBuf, hBuf)));
00356               buf.copyFrom(recYuvExt.subBuf(
00357                 UnitArea(cs.area.chromaFormat, Area(xStart - (clipL ? 0 : MAX_ALF_PADDING_SIZE),
00358                                                     yStart - (clipT ? 0 : MAX_ALF_PADDING_SIZE), wBuf, hBuf))));
00359               // pad top-left unavailable samples for raster slice
00360               if (xStart == xPos && yStart == yPos && (rasterSliceAlfPad & 1))
00361               {
00362                 buf.padBorderPel(MAX_ALF_PADDING_SIZE, 1);
00363               }
00364 
00365               // pad bottom-right unavailable samples for raster slice
00366               if (xEnd == xPos + width && yEnd == yPos + height && (rasterSliceAlfPad & 2))
00367               {
00368                 buf.padBorderPel(MAX_ALF_PADDING_SIZE, 2);
00369               }
00370               buf.extendBorderPel(MAX_ALF_PADDING_SIZE);
00371               buf = buf.subBuf(UnitArea(
00372                 cs.area.chromaFormat, Area(clipL ? 0 : MAX_ALF_PADDING_SIZE, clipT ? 0 : MAX_ALF_PADDING_SIZE, w, h)));
00373 
00374               const Area blkSrc(0, 0, w, h);
00375 
00376               const Area blkDst(xStart >> chromaScaleX, yStart >> chromaScaleY, w >> chromaScaleX, h >> chromaScaleY);
00377               m_filterCcAlf(dstBuf, buf, blkDst, blkSrc, compID, filterCoeff, m_clpRngs, cs, m_alfVBLumaCTUHeight,
00378                             m_alfVBLumaPos);
00379 
00380               xStart = xEnd;
00381             }
00382 
00383             yStart = yEnd;
00384           }
00385         }
00386         else
00387         {
00388           const UnitArea area(m_chromaFormat, Area(xPos, yPos, width, height));
00389 
00390           Area blkDst(xPos >> chromaScaleX, yPos >> chromaScaleY, width >> chromaScaleX, height >> chromaScaleY);
00391           Area blkSrc(xPos, yPos, width, height);
00392 
00393           m_filterCcAlf(dstBuf, recYuvExt, blkDst, blkSrc, compID, filterCoeff, m_clpRngs, cs, m_alfVBLumaCTUHeight,
00394                         m_alfVBLumaPos);
00395         }
00396       }
00397       ctuIdx++;
00398     }
00399   }
00400 }
00401 
00402 void AdaptiveLoopFilter::ALFProcess(CodingStructure& cs)
00403 {
00404 
00405   // set clipping range
00406   m_clpRngs = cs.slice->getClpRngs();
00407 
00408   // set CTU enable flags
00409   for( int compIdx = 0; compIdx < MAX_NUM_COMPONENT; compIdx++ )
00410   {
00411     m_ctuEnableFlag[compIdx] = cs.picture->getAlfCtuEnableFlag( compIdx );
00412     m_ctuAlternative[compIdx] = cs.picture->getAlfCtuAlternativeData( compIdx );
00413   }
00414   short* alfCtuFilterIndex = nullptr;
00415   uint32_t lastSliceIdx = 0xFFFFFFFF;
00416 
00417   PelUnitBuf recYuv = cs.getRecoBuf();
00418   m_tempBuf.copyFrom( recYuv );
00419   PelUnitBuf tmpYuv = m_tempBuf.getBuf( cs.area );
00420   tmpYuv.extendBorderPel( MAX_ALF_FILTER_LENGTH >> 1 );
00421 
00422   const PreCalcValues& pcv = *cs.pcv;
00423 
00424   int ctuIdx = 0;
00425   bool clipTop = false, clipBottom = false, clipLeft = false, clipRight = false;
00426   int numHorVirBndry = 0, numVerVirBndry = 0;
00427   int horVirBndryPos[] = { 0, 0, 0 };
00428   int verVirBndryPos[] = { 0, 0, 0 };
00429 
00430   for( int yPos = 0; yPos < pcv.lumaHeight; yPos += pcv.maxCUHeight )
00431   {
00432     for( int xPos = 0; xPos < pcv.lumaWidth; xPos += pcv.maxCUWidth )
00433     {
00434       // get first CU in CTU
00435       const CodingUnit *cu = cs.getCU( Position(xPos, yPos), CHANNEL_TYPE_LUMA );
00436 
00437       // skip this CTU if ALF is disabled
00438       if (!cu->slice->getTileGroupAlfEnabledFlag(COMPONENT_Y) && !cu->slice->getTileGroupAlfEnabledFlag(COMPONENT_Cb) && !cu->slice->getTileGroupAlfEnabledFlag(COMPONENT_Cr))
00439       {
00440         ctuIdx++;
00441         continue;
00442       }
00443 
00444       // reload ALF APS each time the slice changes during raster scan filtering
00445       if(ctuIdx == 0 || lastSliceIdx != cu->slice->getSliceID() || alfCtuFilterIndex==nullptr)
00446       {
00447         cs.slice = cu->slice;
00448         reconstructCoeffAPSs(cs, true, cu->slice->getTileGroupAlfEnabledFlag(COMPONENT_Cb) || cu->slice->getTileGroupAlfEnabledFlag(COMPONENT_Cr), false);
00449         alfCtuFilterIndex = cu->slice->getPic()->getAlfCtbFilterIndex();
00450         m_ccAlfFilterParam = cu->slice->m_ccAlfFilterParam;
00451       }
00452       lastSliceIdx = cu->slice->getSliceID();
00453 
00454       const int width = ( xPos + pcv.maxCUWidth > pcv.lumaWidth ) ? ( pcv.lumaWidth - xPos ) : pcv.maxCUWidth;
00455       const int height = ( yPos + pcv.maxCUHeight > pcv.lumaHeight ) ? ( pcv.lumaHeight - yPos ) : pcv.maxCUHeight;
00456       bool ctuEnableFlag = m_ctuEnableFlag[COMPONENT_Y][ctuIdx];
00457       for( int compIdx = 1; compIdx < MAX_NUM_COMPONENT; compIdx++ )
00458       {
00459         ctuEnableFlag |= m_ctuEnableFlag[compIdx][ctuIdx] > 0;
00460         if (cu->slice->m_ccAlfFilterParam.ccAlfFilterEnabled[compIdx - 1])
00461         {
00462           ctuEnableFlag |= m_ccAlfFilterControl[compIdx - 1][ctuIdx] > 0;
00463         }
00464       }
00465       int rasterSliceAlfPad = 0;
00466       if( ctuEnableFlag && isCrossedByVirtualBoundaries( cs, xPos, yPos, width, height, clipTop, clipBottom, clipLeft, clipRight, numHorVirBndry, numVerVirBndry, horVirBndryPos, verVirBndryPos, rasterSliceAlfPad ) )
00467       {
00468         int yStart = yPos;
00469         for( int i = 0; i <= numHorVirBndry; i++ )
00470         {
00471           const int yEnd = i == numHorVirBndry ? yPos + height : horVirBndryPos[i];
00472           const int h = yEnd - yStart;
00473           const bool clipT = ( i == 0 && clipTop ) || ( i > 0 ) || ( yStart == 0 );
00474           const bool clipB = ( i == numHorVirBndry && clipBottom ) || ( i < numHorVirBndry ) || ( yEnd == pcv.lumaHeight );
00475           int xStart = xPos;
00476           for( int j = 0; j <= numVerVirBndry; j++ )
00477           {
00478             const int xEnd = j == numVerVirBndry ? xPos + width : verVirBndryPos[j];
00479             const int w = xEnd - xStart;
00480             const bool clipL = ( j == 0 && clipLeft ) || ( j > 0 ) || ( xStart == 0 );
00481             const bool clipR = ( j == numVerVirBndry && clipRight ) || ( j < numVerVirBndry ) || ( xEnd == pcv.lumaWidth );
00482             const int wBuf = w + (clipL ? 0 : MAX_ALF_PADDING_SIZE) + (clipR ? 0 : MAX_ALF_PADDING_SIZE);
00483             const int hBuf = h + (clipT ? 0 : MAX_ALF_PADDING_SIZE) + (clipB ? 0 : MAX_ALF_PADDING_SIZE);
00484             PelUnitBuf buf = m_tempBuf2.subBuf( UnitArea( cs.area.chromaFormat, Area( 0, 0, wBuf, hBuf ) ) );
00485             buf.copyFrom( tmpYuv.subBuf( UnitArea( cs.area.chromaFormat, Area( xStart - (clipL ? 0 : MAX_ALF_PADDING_SIZE), yStart - (clipT ? 0 : MAX_ALF_PADDING_SIZE), wBuf, hBuf ) ) ) );
00486             // pad top-left unavailable samples for raster slice
00487             if ( xStart == xPos && yStart == yPos && ( rasterSliceAlfPad & 1 ) )
00488             {
00489               buf.padBorderPel( MAX_ALF_PADDING_SIZE, 1 );
00490             }
00491 
00492             // pad bottom-right unavailable samples for raster slice
00493             if ( xEnd == xPos + width && yEnd == yPos + height && ( rasterSliceAlfPad & 2 ) )
00494             {
00495               buf.padBorderPel( MAX_ALF_PADDING_SIZE, 2 );
00496             }
00497             buf.extendBorderPel( MAX_ALF_PADDING_SIZE );
00498             buf = buf.subBuf( UnitArea ( cs.area.chromaFormat, Area( clipL ? 0 : MAX_ALF_PADDING_SIZE, clipT ? 0 : MAX_ALF_PADDING_SIZE, w, h ) ) );
00499 
00500             if( m_ctuEnableFlag[COMPONENT_Y][ctuIdx] )
00501             {
00502               const Area blkSrc( 0, 0, w, h );
00503               const Area blkDst( xStart, yStart, w, h );
00504               deriveClassification( m_classifier, buf.get(COMPONENT_Y), blkDst, blkSrc );
00505               short filterSetIndex = alfCtuFilterIndex[ctuIdx];
00506               short *coeff;
00507               Pel *clip;
00508               if (filterSetIndex >= NUM_FIXED_FILTER_SETS)
00509               {
00510                 coeff = m_coeffApsLuma[filterSetIndex - NUM_FIXED_FILTER_SETS];
00511                 clip = m_clippApsLuma[filterSetIndex - NUM_FIXED_FILTER_SETS];
00512               }
00513               else
00514               {
00515                 coeff = m_fixedFilterSetCoeffDec[filterSetIndex];
00516                 clip = m_clipDefault;
00517               }
00518               m_filter7x7Blk(m_classifier, recYuv, buf, blkDst, blkSrc, COMPONENT_Y, coeff, clip, m_clpRngs.comp[COMPONENT_Y], cs
00519                 , m_alfVBLumaCTUHeight
00520                 , m_alfVBLumaPos
00521               );
00522             }
00523 
00524             for( int compIdx = 1; compIdx < MAX_NUM_COMPONENT; compIdx++ )
00525             {
00526               ComponentID compID = ComponentID( compIdx );
00527               const int chromaScaleX = getComponentScaleX( compID, tmpYuv.chromaFormat );
00528               const int chromaScaleY = getComponentScaleY( compID, tmpYuv.chromaFormat );
00529 
00530               if( m_ctuEnableFlag[compIdx][ctuIdx] )
00531               {
00532                 const Area blkSrc( 0, 0, w >> chromaScaleX, h >> chromaScaleY );
00533                 const Area blkDst( xStart >> chromaScaleX, yStart >> chromaScaleY, w >> chromaScaleX, h >> chromaScaleY );
00534                 uint8_t alt_num = m_ctuAlternative[compIdx][ctuIdx];
00535                 m_filter5x5Blk(m_classifier, recYuv, buf, blkDst, blkSrc, compID, m_chromaCoeffFinal[alt_num], m_chromaClippFinal[alt_num], m_clpRngs.comp[compIdx], cs
00536                   , m_alfVBChmaCTUHeight
00537                    , m_alfVBChmaPos );
00538               }
00539               if (cu->slice->m_ccAlfFilterParam.ccAlfFilterEnabled[compIdx - 1])
00540               {
00541                 const int filterIdx = m_ccAlfFilterControl[compIdx - 1][ctuIdx];
00542 
00543                 if (filterIdx != 0)
00544                 {
00545                   const Area blkSrc(0, 0, w, h);
00546                   Area blkDst(xStart >> chromaScaleX, yStart >> chromaScaleY, w >> chromaScaleX, h >> chromaScaleY);
00547 
00548                   const int16_t *filterCoeff = m_ccAlfFilterParam.ccAlfCoeff[compIdx - 1][filterIdx - 1];
00549 
00550                   m_filterCcAlf(recYuv.get(compID), buf, blkDst, blkSrc, compID, filterCoeff, m_clpRngs, cs,
00551                                 m_alfVBLumaCTUHeight, m_alfVBLumaPos);
00552                 }
00553               }
00554             }
00555 
00556             xStart = xEnd;
00557           }
00558 
00559           yStart = yEnd;
00560         }
00561       }
00562       else
00563       {
00564         const UnitArea area( cs.area.chromaFormat, Area( xPos, yPos, width, height ) );
00565         if( m_ctuEnableFlag[COMPONENT_Y][ctuIdx] )
00566         {
00567           Area blk( xPos, yPos, width, height );
00568           deriveClassification( m_classifier, tmpYuv.get( COMPONENT_Y ), blk, blk );
00569           short filterSetIndex = alfCtuFilterIndex[ctuIdx];
00570           short *coeff;
00571           Pel *clip;
00572           if (filterSetIndex >= NUM_FIXED_FILTER_SETS)
00573           {
00574             coeff = m_coeffApsLuma[filterSetIndex - NUM_FIXED_FILTER_SETS];
00575             clip = m_clippApsLuma[filterSetIndex - NUM_FIXED_FILTER_SETS];
00576           }
00577           else
00578           {
00579             coeff = m_fixedFilterSetCoeffDec[filterSetIndex];
00580             clip = m_clipDefault;
00581           }
00582           m_filter7x7Blk(m_classifier, recYuv, tmpYuv, blk, blk, COMPONENT_Y, coeff, clip, m_clpRngs.comp[COMPONENT_Y],
00583                          cs, m_alfVBLumaCTUHeight, m_alfVBLumaPos);
00584         }
00585 
00586         for( int compIdx = 1; compIdx < MAX_NUM_COMPONENT; compIdx++ )
00587         {
00588           ComponentID compID = ComponentID( compIdx );
00589           const int chromaScaleX = getComponentScaleX( compID, tmpYuv.chromaFormat );
00590           const int chromaScaleY = getComponentScaleY( compID, tmpYuv.chromaFormat );
00591 
00592           if (m_ctuEnableFlag[compIdx][ctuIdx])
00593           {
00594             Area    blk(xPos >> chromaScaleX, yPos >> chromaScaleY, width >> chromaScaleX, height >> chromaScaleY);
00595             uint8_t alt_num = m_ctuAlternative[compIdx][ctuIdx];
00596             m_filter5x5Blk(m_classifier, recYuv, tmpYuv, blk, blk, compID, m_chromaCoeffFinal[alt_num],
00597                            m_chromaClippFinal[alt_num], m_clpRngs.comp[compIdx], cs, m_alfVBChmaCTUHeight,
00598                            m_alfVBChmaPos);
00599           }
00600           if (cu->slice->m_ccAlfFilterParam.ccAlfFilterEnabled[compIdx - 1])
00601           {
00602             const int filterIdx = m_ccAlfFilterControl[compIdx - 1][ctuIdx];
00603 
00604             if (filterIdx != 0)
00605             {
00606               Area blkDst(xPos >> chromaScaleX, yPos >> chromaScaleY, width >> chromaScaleX, height >> chromaScaleY);
00607               Area blkSrc(xPos, yPos, width, height);
00608 
00609               const int16_t *filterCoeff = m_ccAlfFilterParam.ccAlfCoeff[compIdx - 1][filterIdx - 1];
00610 
00611               m_filterCcAlf(recYuv.get(compID), tmpYuv, blkDst, blkSrc, compID, filterCoeff, m_clpRngs, cs,
00612                             m_alfVBLumaCTUHeight, m_alfVBLumaPos);
00613             }
00614           }
00615         }
00616       }
00617       ctuIdx++;
00618     }
00619   }
00620 }
00621 
00622 void AdaptiveLoopFilter::reconstructCoeffAPSs(CodingStructure& cs, bool luma, bool chroma, bool isRdo)
00623 {
00624   //luma
00625   APS** aps = cs.slice->getAlfAPSs();
00626   AlfParam alfParamTmp;
00627   APS* curAPS;
00628   if (luma)
00629   {
00630     for (int i = 0; i < cs.slice->getTileGroupNumAps(); i++)
00631     {
00632       int apsIdx = cs.slice->getTileGroupApsIdLuma()[i];
00633       curAPS = aps[apsIdx];
00634       CHECK(curAPS == NULL, "invalid APS");
00635       alfParamTmp = curAPS->getAlfAPSParam();
00636       reconstructCoeff(alfParamTmp, CHANNEL_TYPE_LUMA, isRdo, true);
00637       memcpy(m_coeffApsLuma[i], m_coeffFinal, sizeof(m_coeffFinal));
00638       memcpy(m_clippApsLuma[i], m_clippFinal, sizeof(m_clippFinal));
00639     }
00640   }
00641 
00642   //chroma
00643   if (chroma)
00644   {
00645     int apsIdxChroma = cs.slice->getTileGroupApsIdChroma();
00646     curAPS = aps[apsIdxChroma];
00647     m_alfParamChroma = &curAPS->getAlfAPSParam();
00648     alfParamTmp = *m_alfParamChroma;
00649     reconstructCoeff(alfParamTmp, CHANNEL_TYPE_CHROMA, isRdo, true);
00650   }
00651 }
00652 
00653 void AdaptiveLoopFilter::reconstructCoeff( AlfParam& alfParam, ChannelType channel, const bool isRdo, const bool isRedo )
00654 {
00655   int factor = isRdo ? 0 : (1 << (m_NUM_BITS - 1));
00656   AlfFilterType filterType = isLuma( channel ) ? ALF_FILTER_7 : ALF_FILTER_5;
00657   int numClasses = isLuma( channel ) ? MAX_NUM_ALF_CLASSES : 1;
00658   int numCoeff = filterType == ALF_FILTER_5 ? 7 : 13;
00659   int numCoeffMinus1 = numCoeff - 1;
00660   const int numAlts = isLuma( channel ) ? 1 : alfParam.numAlternativesChroma;
00661 
00662   for( int altIdx = 0; altIdx < numAlts; ++ altIdx )
00663   {
00664     int numFilters = isLuma( channel ) ? alfParam.numLumaFilters : 1;
00665     short* coeff = isLuma( channel ) ? alfParam.lumaCoeff : alfParam.chromaCoeff[altIdx];
00666     Pel* clipp = isLuma( channel ) ? alfParam.lumaClipp : alfParam.chromaClipp[altIdx];
00667 
00668     for( int filterIdx = 0; filterIdx < numFilters; filterIdx++ )
00669     {
00670       coeff[filterIdx* MAX_NUM_ALF_LUMA_COEFF + numCoeffMinus1] = factor;
00671     }
00672 
00673     if( isChroma( channel ) )
00674     {
00675       for( int coeffIdx = 0; coeffIdx < numCoeffMinus1; ++coeffIdx )
00676       {
00677         m_chromaCoeffFinal[altIdx][coeffIdx] = coeff[coeffIdx];
00678         int clipIdx = alfParam.nonLinearFlag[channel] ? clipp[coeffIdx] : 0;
00679         m_chromaClippFinal[altIdx][coeffIdx] = isRdo ? clipIdx : m_alfClippingValues[channel][clipIdx];
00680       }
00681       m_chromaCoeffFinal[altIdx][numCoeffMinus1] = factor;
00682       m_chromaClippFinal[altIdx][numCoeffMinus1] = isRdo ? 0 : m_alfClippingValues[channel][0];
00683       continue;
00684     }
00685     for( int classIdx = 0; classIdx < numClasses; classIdx++ )
00686     {
00687       int filterIdx = alfParam.filterCoeffDeltaIdx[classIdx];
00688 
00689       CHECK(!(filterIdx >= 0 && filterIdx < alfParam.numLumaFilters), "Bad coeff delta idx in ALF");
00690       for (int coeffIdx = 0; coeffIdx < numCoeffMinus1; ++coeffIdx)
00691       {
00692         m_coeffFinal[classIdx * MAX_NUM_ALF_LUMA_COEFF + coeffIdx] = coeff[filterIdx * MAX_NUM_ALF_LUMA_COEFF + coeffIdx];
00693       }
00694       m_coeffFinal[classIdx* MAX_NUM_ALF_LUMA_COEFF + numCoeffMinus1] = factor;
00695       m_clippFinal[classIdx* MAX_NUM_ALF_LUMA_COEFF + numCoeffMinus1] = isRdo ? 0 : m_alfClippingValues[channel][0];
00696       for( int coeffIdx = 0; coeffIdx < numCoeffMinus1; ++coeffIdx )
00697       {
00698         int clipIdx = alfParam.nonLinearFlag[channel] ? clipp[filterIdx * MAX_NUM_ALF_LUMA_COEFF + coeffIdx] : 0;
00699         CHECK(!(clipIdx >= 0 && clipIdx < MaxAlfNumClippingValues), "Bad clip idx in ALF");
00700         m_clippFinal[classIdx * MAX_NUM_ALF_LUMA_COEFF + coeffIdx] = isRdo ? clipIdx : m_alfClippingValues[channel][clipIdx];
00701       }
00702       m_clippFinal[classIdx* MAX_NUM_ALF_LUMA_COEFF + numCoeffMinus1] =
00703         isRdo ? 0 :
00704         m_alfClippingValues[channel][0];
00705     }
00706   }
00707 }
00708 
00709 void AdaptiveLoopFilter::create( const int picWidth, const int picHeight, const ChromaFormat format, const int maxCUWidth, const int maxCUHeight, const int maxCUDepth, const int inputBitDepth[MAX_NUM_CHANNEL_TYPE] )
00710 {
00711   destroy();
00712   std::memcpy( m_inputBitDepth, inputBitDepth, sizeof( m_inputBitDepth ) );
00713   m_picWidth = picWidth;
00714   m_picHeight = picHeight;
00715   m_maxCUWidth = maxCUWidth;
00716   m_maxCUHeight = maxCUHeight;
00717   m_maxCUDepth = maxCUDepth;
00718   m_chromaFormat = format;
00719 
00720   m_numCTUsInWidth = ( m_picWidth / m_maxCUWidth ) + ( ( m_picWidth % m_maxCUWidth ) ? 1 : 0 );
00721   m_numCTUsInHeight = ( m_picHeight / m_maxCUHeight ) + ( ( m_picHeight % m_maxCUHeight ) ? 1 : 0 );
00722   m_numCTUsInPic = m_numCTUsInHeight * m_numCTUsInWidth;
00723   m_filterShapesCcAlf[0].push_back(AlfFilterShape(size_CC_ALF));
00724   m_filterShapesCcAlf[1].push_back(AlfFilterShape(size_CC_ALF));
00725   m_filterShapes[CHANNEL_TYPE_LUMA].push_back( AlfFilterShape( 7 ) );
00726   m_filterShapes[CHANNEL_TYPE_CHROMA].push_back( AlfFilterShape( 5 ) );
00727   m_alfVBLumaPos = m_maxCUHeight - ALF_VB_POS_ABOVE_CTUROW_LUMA;
00728   m_alfVBChmaPos = (m_maxCUHeight >> ((m_chromaFormat == CHROMA_420) ? 1 : 0)) - ALF_VB_POS_ABOVE_CTUROW_CHMA;
00729 
00730   m_alfVBLumaCTUHeight = m_maxCUHeight;
00731   m_alfVBChmaCTUHeight = (m_maxCUHeight >> ((m_chromaFormat == CHROMA_420) ? 1 : 0));
00732 
00733   static_assert( AlfNumClippingValues[CHANNEL_TYPE_LUMA] > 0, "AlfNumClippingValues[CHANNEL_TYPE_LUMA] must be at least one" );
00734   m_alfClippingValues[CHANNEL_TYPE_LUMA][0] = 1 << m_inputBitDepth[CHANNEL_TYPE_LUMA];
00735   int shiftLuma = m_inputBitDepth[CHANNEL_TYPE_LUMA] - 8;
00736   for (int i = 1; i < AlfNumClippingValues[CHANNEL_TYPE_LUMA]; ++i)
00737   {
00738     m_alfClippingValues[CHANNEL_TYPE_LUMA][i] = 1 << (7 - 2 * i + shiftLuma);
00739   }
00740   static_assert( AlfNumClippingValues[CHANNEL_TYPE_CHROMA] > 0, "AlfNumClippingValues[CHANNEL_TYPE_CHROMA] must be at least one" );
00741   m_alfClippingValues[CHANNEL_TYPE_CHROMA][0] = 1 << m_inputBitDepth[CHANNEL_TYPE_CHROMA];
00742   int shiftChroma = m_inputBitDepth[CHANNEL_TYPE_CHROMA] - 8;
00743   for (int i = 1; i < AlfNumClippingValues[CHANNEL_TYPE_CHROMA]; ++i)
00744   {
00745     m_alfClippingValues[CHANNEL_TYPE_CHROMA][i] = 1 << (7 - 2 * i + shiftChroma);
00746   }
00747   if (m_created)
00748   {
00749     return;
00750   }
00751 
00752   m_tempBuf.destroy();
00753   // NOTE: make border 1 sample wider to avoid out-of-bounds memory access in SIMD code (simdDeriveClassificationBlk
00754   // function)
00755   m_tempBuf.create(format, Area(0, 0, picWidth, picHeight), maxCUWidth, (MAX_ALF_FILTER_LENGTH + 1) >> 1, 0, false);
00756   m_tempBuf2.destroy();
00757   m_tempBuf2.create( format, Area( 0, 0, maxCUWidth + (MAX_ALF_PADDING_SIZE << 1), maxCUHeight + (MAX_ALF_PADDING_SIZE << 1) ), maxCUWidth, MAX_ALF_PADDING_SIZE, 0, false );
00758 
00759   // Classification
00760   if ( m_classifier == nullptr )
00761   {
00762     m_classifier = new AlfClassifier*[picHeight];
00763     m_classifier[0] = new AlfClassifier[picWidth * picHeight];
00764 
00765     for (int i = 1; i < picHeight; i++)
00766     {
00767       m_classifier[i] = m_classifier[0] + i * picWidth;
00768     }
00769   }
00770 
00771   for (int filterSetIndex = 0; filterSetIndex < NUM_FIXED_FILTER_SETS; filterSetIndex++)
00772   {
00773     for (int classIdx = 0; classIdx < MAX_NUM_ALF_CLASSES; classIdx++)
00774     {
00775       int fixedFilterIdx = m_classToFilterMapping[filterSetIndex][classIdx];
00776       for (int i = 0; i < MAX_NUM_ALF_LUMA_COEFF - 1; i++)
00777       {
00778        m_fixedFilterSetCoeffDec[filterSetIndex][classIdx * MAX_NUM_ALF_LUMA_COEFF + i] = m_fixedFilterSetCoeff[fixedFilterIdx][i];
00779       }
00780       m_fixedFilterSetCoeffDec[filterSetIndex][classIdx * MAX_NUM_ALF_LUMA_COEFF + MAX_NUM_ALF_LUMA_COEFF - 1] = (1 << (m_NUM_BITS - 1));
00781     }
00782   }
00783   for (int i = 0; i < MAX_NUM_ALF_LUMA_COEFF * MAX_NUM_ALF_CLASSES; i++)
00784   {
00785     m_clipDefault[i] = m_alfClippingValues[CHANNEL_TYPE_LUMA][0];
00786   }
00787   m_created = true;
00788 
00789   m_ccAlfFilterControl[0] = new uint8_t[m_numCTUsInPic];
00790   m_ccAlfFilterControl[1] = new uint8_t[m_numCTUsInPic];
00791 }
00792 
00793 void AdaptiveLoopFilter::destroy()
00794 {
00795   if (!m_created)
00796   {
00797     return;
00798   }
00799 
00800   if( m_classifier )
00801   {
00802     delete[] m_classifier[0];
00803     delete[] m_classifier;
00804     m_classifier = nullptr;
00805   }
00806 
00807   m_tempBuf.destroy();
00808   m_tempBuf2.destroy();
00809   m_filterShapes[CHANNEL_TYPE_LUMA].clear();
00810   m_filterShapes[CHANNEL_TYPE_CHROMA].clear();
00811   m_created = false;
00812 
00813   m_filterShapesCcAlf[0].clear();
00814   m_filterShapesCcAlf[1].clear();
00815   if ( m_ccAlfFilterControl[0] )
00816   {
00817     delete [] m_ccAlfFilterControl[0];
00818     m_ccAlfFilterControl[0] = nullptr;
00819   }
00820 
00821   if ( m_ccAlfFilterControl[1] )
00822   {
00823     delete [] m_ccAlfFilterControl[1];
00824     m_ccAlfFilterControl[1] = nullptr;
00825   }
00826 }
