00828 void AdaptiveLoopFilter::deriveClassification( AlfClassifier** classifier, const CPelBuf& srcLuma, const Area& blkDst, const Area& blk )
00829 {
00830   int height = blk.pos().y + blk.height;
00831   int width = blk.pos().x + blk.width;
00832 
00833   for( int i = blk.pos().y; i < height; i += m_CLASSIFICATION_BLK_SIZE )
00834   {
00835     int nHeight = std::min( i + m_CLASSIFICATION_BLK_SIZE, height ) - i;
00836 
00837     for( int j = blk.pos().x; j < width; j += m_CLASSIFICATION_BLK_SIZE )
00838     {
00839       int nWidth = std::min( j + m_CLASSIFICATION_BLK_SIZE, width ) - j;
00840       m_deriveClassificationBlk(classifier, m_laplacian, srcLuma, Area( j - blk.pos().x + blkDst.pos().x, i - blk.pos().y + blkDst.pos().y, nWidth, nHeight ), Area(j, i, nWidth, nHeight), m_inputBitDepth[CHANNEL_TYPE_LUMA] + 4
00841         , m_alfVBLumaCTUHeight
00842         , m_alfVBLumaPos
00843       );
00844     }
00845   }
00846 }
00847 
00848 void AdaptiveLoopFilter::deriveClassificationBlk(AlfClassifier **classifier, int **laplacian[NUM_DIRECTIONS],
00849                                                  const CPelBuf &srcLuma, const Area &blkDst, const Area &blk,
00850                                                  const int shift, const int vbCTUHeight, int vbPos)
00851 {
00852   CHECK((vbCTUHeight & (vbCTUHeight - 1)) != 0, "vbCTUHeight must be a power of 2");
00853 
00854   static const int th[16] = { 0, 1, 2, 2, 2, 2, 2, 3, 3, 3, 3, 3, 3, 3, 3, 4 };
00855   const int stride = srcLuma.stride;
00856   const Pel* src = srcLuma.buf;
00857   const int maxActivity = 15;
00858 
00859   int fl = 2;
00860   int flP1 = fl + 1;
00861   int fl2 = 2 * fl;
00862 
00863   int mainDirection, secondaryDirection, dirTempHV, dirTempD;
00864 
00865   int pixY;
00866   int height = blk.height + fl2;
00867   int width = blk.width + fl2;
00868   int posX = blk.pos().x;
00869   int posY = blk.pos().y;
00870   int startHeight = posY - flP1;
00871 
00872   for( int i = 0; i < height; i += 2 )
00873   {
00874     int yoffset = ( i + 1 + startHeight ) * stride - flP1;
00875     const Pel *src0 = &src[yoffset - stride];
00876     const Pel *src1 = &src[yoffset];
00877     const Pel *src2 = &src[yoffset + stride];
00878     const Pel *src3 = &src[yoffset + stride * 2];
00879 
00880     const int y = blkDst.pos().y - 2 + i;
00881     if (y > 0 && (y & (vbCTUHeight - 1)) == vbPos - 2)
00882     {
00883       src3 = &src[yoffset + stride];
00884     }
00885     else if (y > 0 && (y & (vbCTUHeight - 1)) == vbPos)
00886     {
00887       src0 = &src[yoffset];
00888     }
00889     int* pYver = laplacian[VER][i];
00890     int* pYhor = laplacian[HOR][i];
00891     int* pYdig0 = laplacian[DIAG0][i];
00892     int* pYdig1 = laplacian[DIAG1][i];
00893 
00894     for( int j = 0; j < width; j += 2 )
00895     {
00896       pixY = j + 1 + posX;
00897       const Pel *pY = src1 + pixY;
00898       const Pel* pYdown = src0 + pixY;
00899       const Pel* pYup = src2 + pixY;
00900       const Pel* pYup2 = src3 + pixY;
00901 
00902       const Pel y0 = pY[0] << 1;
00903       const Pel yup1 = pYup[1] << 1;
00904 
00905       pYver[j] = abs( y0 - pYdown[0] - pYup[0] ) + abs( yup1 - pY[1] - pYup2[1] );
00906       pYhor[j] = abs( y0 - pY[1] - pY[-1] ) + abs( yup1 - pYup[2] - pYup[0] );
00907       pYdig0[j] = abs( y0 - pYdown[-1] - pYup[1] ) + abs( yup1 - pY[0] - pYup2[2] );
00908       pYdig1[j] = abs( y0 - pYup[-1] - pYdown[1] ) + abs( yup1 - pYup2[0] - pY[2] );
00909 
00910       if( j > 4 && ( j - 6 ) % 4 == 0 )
00911       {
00912         int jM6 = j - 6;
00913         int jM4 = j - 4;
00914         int jM2 = j - 2;
00915         pYver[jM6] += pYver[jM4] + pYver[jM2] + pYver[j];
00916         pYhor[jM6] += pYhor[jM4] + pYhor[jM2] + pYhor[j];
00917         pYdig0[jM6] += pYdig0[jM4] + pYdig0[jM2] + pYdig0[j];
00918         pYdig1[jM6] += pYdig1[jM4] + pYdig1[jM2] + pYdig1[j];
00919       }
00920     }
00921   }
00922 
00923   // classification block size
00924   const int clsSizeY = 4;
00925   const int clsSizeX = 4;
00926 
00927   for( int i = 0; i < blk.height; i += clsSizeY )
00928   {
00929     int* pYver = laplacian[VER][i];
00930     int* pYver2 = laplacian[VER][i + 2];
00931     int* pYver4 = laplacian[VER][i + 4];
00932     int* pYver6 = laplacian[VER][i + 6];
00933 
00934     int* pYhor = laplacian[HOR][i];
00935     int* pYhor2 = laplacian[HOR][i + 2];
00936     int* pYhor4 = laplacian[HOR][i + 4];
00937     int* pYhor6 = laplacian[HOR][i + 6];
00938 
00939     int* pYdig0 = laplacian[DIAG0][i];
00940     int* pYdig02 = laplacian[DIAG0][i + 2];
00941     int* pYdig04 = laplacian[DIAG0][i + 4];
00942     int* pYdig06 = laplacian[DIAG0][i + 6];
00943 
00944     int* pYdig1 = laplacian[DIAG1][i];
00945     int* pYdig12 = laplacian[DIAG1][i + 2];
00946     int* pYdig14 = laplacian[DIAG1][i + 4];
00947     int* pYdig16 = laplacian[DIAG1][i + 6];
00948 
00949     for( int j = 0; j < blk.width; j += clsSizeX )
00950     {
00951       int sumV = 0; int sumH = 0; int sumD0 = 0; int sumD1 = 0;
00952       if (((i + blkDst.pos().y) % vbCTUHeight) == (vbPos - 4))
00953       {
00954         sumV = pYver[j] + pYver2[j] + pYver4[j];
00955         sumH = pYhor[j] + pYhor2[j] + pYhor4[j];
00956         sumD0 = pYdig0[j] + pYdig02[j] + pYdig04[j];
00957         sumD1 = pYdig1[j] + pYdig12[j] + pYdig14[j];
00958       }
00959       else if (((i + blkDst.pos().y) % vbCTUHeight) == vbPos)
00960       {
00961         sumV = pYver2[j] + pYver4[j] + pYver6[j];
00962         sumH = pYhor2[j] + pYhor4[j] + pYhor6[j];
00963         sumD0 = pYdig02[j] + pYdig04[j] + pYdig06[j];
00964         sumD1 = pYdig12[j] + pYdig14[j] + pYdig16[j];
00965       }
00966       else
00967       {
00968         sumV = pYver[j] + pYver2[j] + pYver4[j] + pYver6[j];
00969         sumH = pYhor[j] + pYhor2[j] + pYhor4[j] + pYhor6[j];
00970         sumD0 = pYdig0[j] + pYdig02[j] + pYdig04[j] + pYdig06[j];
00971         sumD1 = pYdig1[j] + pYdig12[j] + pYdig14[j] + pYdig16[j];
00972       }
00973 
00974       int tempAct = sumV + sumH;
00975       int activity = 0;
00976 
00977       const int y = (i + blkDst.pos().y) & (vbCTUHeight - 1);
00978       if (y == vbPos - 4 || y == vbPos)
00979       {
00980         activity = (Pel)Clip3<int>(0, maxActivity, (tempAct * 96) >> shift);
00981       }
00982       else
00983       {
00984         activity = (Pel)Clip3<int>(0, maxActivity, (tempAct * 64) >> shift);
00985       }
00986       int classIdx = th[activity];
00987 
00988       int hv1, hv0, d1, d0, hvd1, hvd0;
00989 
00990       if( sumV > sumH )
00991       {
00992         hv1 = sumV;
00993         hv0 = sumH;
00994         dirTempHV = 1;
00995       }
00996       else
00997       {
00998         hv1 = sumH;
00999         hv0 = sumV;
01000         dirTempHV = 3;
01001       }
01002       if( sumD0 > sumD1 )
01003       {
01004         d1 = sumD0;
01005         d0 = sumD1;
01006         dirTempD = 0;
01007       }
01008       else
01009       {
01010         d1 = sumD1;
01011         d0 = sumD0;
01012         dirTempD = 2;
01013       }
01014       if( (uint32_t)d1 * (uint32_t)hv0 > (uint32_t)hv1 * (uint32_t)d0 )
01015       {
01016         hvd1 = d1;
01017         hvd0 = d0;
01018         mainDirection = dirTempD;
01019         secondaryDirection = dirTempHV;
01020       }
01021       else
01022       {
01023         hvd1 = hv1;
01024         hvd0 = hv0;
01025         mainDirection = dirTempHV;
01026         secondaryDirection = dirTempD;
01027       }
01028 
01029       int directionStrength = 0;
01030       if( hvd1 > 2 * hvd0 )
01031       {
01032         directionStrength = 1;
01033       }
01034       if( hvd1 * 2 > 9 * hvd0 )
01035       {
01036         directionStrength = 2;
01037       }
01038 
01039       if( directionStrength )
01040       {
01041         classIdx += ( ( ( mainDirection & 0x1 ) << 1 ) + directionStrength ) * 5;
01042       }
01043 
01044       static const int transposeTable[8] = { 0, 1, 0, 2, 2, 3, 1, 3 };
01045       int transposeIdx = transposeTable[mainDirection * 2 + ( secondaryDirection >> 1 )];
01046 
01047       int yOffset = i + blkDst.pos().y;
01048       int xOffset = j + blkDst.pos().x;
01049 
01050       AlfClassifier *cl0 = classifier[yOffset] + xOffset;
01051       AlfClassifier *cl1 = classifier[yOffset + 1] + xOffset;
01052       AlfClassifier *cl2 = classifier[yOffset + 2] + xOffset;
01053       AlfClassifier *cl3 = classifier[yOffset + 3] + xOffset;
01054       cl0[0] = cl0[1] = cl0[2] = cl0[3] = cl1[0] = cl1[1] = cl1[2] = cl1[3] = cl2[0] = cl2[1] = cl2[2] = cl2[3] = cl3[0] = cl3[1] = cl3[2] = cl3[3] = AlfClassifier( classIdx, transposeIdx );
01055     }
01056   }
01057 }
01058 
01059 template<AlfFilterType filtType>
01060 void AdaptiveLoopFilter::filterBlk(AlfClassifier **classifier, const PelUnitBuf &recDst, const CPelUnitBuf &recSrc,
01061                                    const Area &blkDst, const Area &blk, const ComponentID compId,
01062                                    const short *filterSet, const Pel *fClipSet, const ClpRng &clpRng,
01063                                    CodingStructure &cs, const int vbCTUHeight, int vbPos)
01064 {
01065   CHECK((vbCTUHeight & (vbCTUHeight - 1)) != 0, "vbCTUHeight must be a power of 2");
01066 
01067   const bool bChroma = isChroma( compId );
01068   if( bChroma )
01069   {
01070     CHECK( filtType != 0, "Chroma needs to have filtType == 0" );
01071   }
01072 
01073   const CPelBuf srcLuma = recSrc.get( compId );
01074   PelBuf dstLuma = recDst.get( compId );
01075 
01076   const int srcStride = srcLuma.stride;
01077   const int dstStride = dstLuma.stride;
01078 
01079   const int startHeight = blk.y;
01080   const int endHeight = blk.y + blk.height;
01081   const int startWidth = blk.x;
01082   const int endWidth = blk.x + blk.width;
01083 
01084   const Pel* src = srcLuma.buf;
01085   Pel* dst = dstLuma.buf + blkDst.y * dstStride;
01086 
01087   const Pel *pImgYPad0, *pImgYPad1, *pImgYPad2, *pImgYPad3, *pImgYPad4, *pImgYPad5, *pImgYPad6;
01088   const Pel *pImg0, *pImg1, *pImg2, *pImg3, *pImg4, *pImg5, *pImg6;
01089 
01090   const short *coef = filterSet;
01091   const Pel *clip = fClipSet;
01092   const int shift = m_NUM_BITS - 1;
01093 
01094   const int offset = 1 << ( shift - 1 );
01095 
01096   int transposeIdx = 0;
01097   const int clsSizeY = 4;
01098   const int clsSizeX = 4;
01099 
01100   CHECK( startHeight % clsSizeY, "Wrong startHeight in filtering" );
01101   CHECK( startWidth % clsSizeX, "Wrong startWidth in filtering" );
01102   CHECK( ( endHeight - startHeight ) % clsSizeY, "Wrong endHeight in filtering" );
01103   CHECK( ( endWidth - startWidth ) % clsSizeX, "Wrong endWidth in filtering" );
01104 
01105   AlfClassifier *pClass = nullptr;
01106 
01107   int dstStride2 = dstStride * clsSizeY;
01108   int srcStride2 = srcStride * clsSizeY;
01109 
01110   std::array<int, MAX_NUM_ALF_LUMA_COEFF> filterCoeff;
01111   std::array<int, MAX_NUM_ALF_LUMA_COEFF> filterClipp;
01112 
01113   pImgYPad0 = src + startHeight * srcStride + startWidth;
01114   pImgYPad1 = pImgYPad0 + srcStride;
01115   pImgYPad2 = pImgYPad0 - srcStride;
01116   pImgYPad3 = pImgYPad1 + srcStride;
01117   pImgYPad4 = pImgYPad2 - srcStride;
01118   pImgYPad5 = pImgYPad3 + srcStride;
01119   pImgYPad6 = pImgYPad4 - srcStride;
01120 
01121   Pel* pRec0 = dst + blkDst.x;
01122   Pel* pRec1 = pRec0 + dstStride;
01123 
01124   for( int i = 0; i < endHeight - startHeight; i += clsSizeY )
01125   {
01126     if( !bChroma )
01127     {
01128       pClass = classifier[blkDst.y + i] + blkDst.x;
01129     }
01130 
01131     for( int j = 0; j < endWidth - startWidth; j += clsSizeX )
01132     {
01133       if( !bChroma )
01134       {
01135         AlfClassifier& cl = pClass[j];
01136         transposeIdx = cl.transposeIdx;
01137         coef = filterSet + cl.classIdx * MAX_NUM_ALF_LUMA_COEFF;
01138         clip = fClipSet + cl.classIdx * MAX_NUM_ALF_LUMA_COEFF;
01139       }
01140 
01141       if( filtType == ALF_FILTER_7 )
01142       {
01143         if( transposeIdx == 1 )
01144         {
01145           filterCoeff = { coef[9], coef[4], coef[10], coef[8], coef[1], coef[5], coef[11], coef[7], coef[3], coef[0], coef[2], coef[6], coef[12] };
01146           filterClipp = { clip[9], clip[4], clip[10], clip[8], clip[1], clip[5], clip[11], clip[7], clip[3], clip[0], clip[2], clip[6], clip[12] };
01147         }
01148         else if( transposeIdx == 2 )
01149         {
01150           filterCoeff = { coef[0], coef[3], coef[2], coef[1], coef[8], coef[7], coef[6], coef[5], coef[4], coef[9], coef[10], coef[11], coef[12] };
01151           filterClipp = { clip[0], clip[3], clip[2], clip[1], clip[8], clip[7], clip[6], clip[5], clip[4], clip[9], clip[10], clip[11], clip[12] };
01152         }
01153         else if( transposeIdx == 3 )
01154         {
01155           filterCoeff = { coef[9], coef[8], coef[10], coef[4], coef[3], coef[7], coef[11], coef[5], coef[1], coef[0], coef[2], coef[6], coef[12] };
01156           filterClipp = { clip[9], clip[8], clip[10], clip[4], clip[3], clip[7], clip[11], clip[5], clip[1], clip[0], clip[2], clip[6], clip[12] };
01157         }
01158         else
01159         {
01160           filterCoeff = { coef[0], coef[1], coef[2], coef[3], coef[4], coef[5], coef[6], coef[7], coef[8], coef[9], coef[10], coef[11], coef[12] };
01161           filterClipp = { clip[0], clip[1], clip[2], clip[3], clip[4], clip[5], clip[6], clip[7], clip[8], clip[9], clip[10], clip[11], clip[12] };
01162         }
01163       }
01164       else
01165       {
01166         if( transposeIdx == 1 )
01167         {
01168           filterCoeff = { coef[4], coef[1], coef[5], coef[3], coef[0], coef[2], coef[6] };
01169           filterClipp = { clip[4], clip[1], clip[5], clip[3], clip[0], clip[2], clip[6] };
01170         }
01171         else if( transposeIdx == 2 )
01172         {
01173           filterCoeff = { coef[0], coef[3], coef[2], coef[1], coef[4], coef[5], coef[6] };
01174           filterClipp = { clip[0], clip[3], clip[2], clip[1], clip[4], clip[5], clip[6] };
01175         }
01176         else if( transposeIdx == 3 )
01177         {
01178           filterCoeff = { coef[4], coef[3], coef[5], coef[1], coef[0], coef[2], coef[6] };
01179           filterClipp = { clip[4], clip[3], clip[5], clip[1], clip[0], clip[2], clip[6] };
01180         }
01181         else
01182         {
01183           filterCoeff = { coef[0], coef[1], coef[2], coef[3], coef[4], coef[5], coef[6] };
01184           filterClipp = { clip[0], clip[1], clip[2], clip[3], clip[4], clip[5], clip[6] };
01185         }
01186       }
01187 
01188       for( int ii = 0; ii < clsSizeY; ii++ )
01189       {
01190         pImg0 = pImgYPad0 + j + ii * srcStride;
01191         pImg1 = pImgYPad1 + j + ii * srcStride;
01192         pImg2 = pImgYPad2 + j + ii * srcStride;
01193         pImg3 = pImgYPad3 + j + ii * srcStride;
01194         pImg4 = pImgYPad4 + j + ii * srcStride;
01195         pImg5 = pImgYPad5 + j + ii * srcStride;
01196         pImg6 = pImgYPad6 + j + ii * srcStride;
01197 
01198         pRec1 = pRec0 + j + ii * dstStride;
01199 
01200         const int yVb = (blkDst.y + i + ii) & (vbCTUHeight - 1);
01201         if (yVb < vbPos && (yVb >= vbPos - (bChroma ? 2 : 4)))   // above
01202         {
01203           pImg1 = (yVb == vbPos - 1) ? pImg0 : pImg1;
01204           pImg3 = (yVb >= vbPos - 2) ? pImg1 : pImg3;
01205           pImg5 = (yVb >= vbPos - 3) ? pImg3 : pImg5;
01206 
01207           pImg2 = (yVb == vbPos - 1) ? pImg0 : pImg2;
01208           pImg4 = (yVb >= vbPos - 2) ? pImg2 : pImg4;
01209           pImg6 = (yVb >= vbPos - 3) ? pImg4 : pImg6;
01210         }
01211         else if (yVb >= vbPos && (yVb <= vbPos + (bChroma ? 1 : 3)))   // bottom
01212         {
01213           pImg2 = (yVb == vbPos) ? pImg0 : pImg2;
01214           pImg4 = (yVb <= vbPos + 1) ? pImg2 : pImg4;
01215           pImg6 = (yVb <= vbPos + 2) ? pImg4 : pImg6;
01216 
01217           pImg1 = (yVb == vbPos) ? pImg0 : pImg1;
01218           pImg3 = (yVb <= vbPos + 1) ? pImg1 : pImg3;
01219           pImg5 = (yVb <= vbPos + 2) ? pImg3 : pImg5;
01220         }
01221         bool isNearVBabove = yVb < vbPos && (yVb >= vbPos - 1);
01222         bool isNearVBbelow = yVb >= vbPos && (yVb <= vbPos);
01223         for( int jj = 0; jj < clsSizeX; jj++ )
01224         {
01225           int32_t   sum  = 0;
01226           const Pel curr = pImg0[+0];
01227           if( filtType == ALF_FILTER_7 )
01228           {
01229             sum += filterCoeff[0] * ( clipALF(filterClipp[0], curr, pImg5[+0], pImg6[+0]) );
01230 
01231             sum += filterCoeff[1] * ( clipALF(filterClipp[1], curr, pImg3[+1], pImg4[-1]) );
01232             sum += filterCoeff[2] * ( clipALF(filterClipp[2], curr, pImg3[+0], pImg4[+0]) );
01233             sum += filterCoeff[3] * ( clipALF(filterClipp[3], curr, pImg3[-1], pImg4[+1]) );
01234 
01235             sum += filterCoeff[4] * ( clipALF(filterClipp[4], curr, pImg1[+2], pImg2[-2]) );
01236             sum += filterCoeff[5] * ( clipALF(filterClipp[5], curr, pImg1[+1], pImg2[-1]) );
01237             sum += filterCoeff[6] * ( clipALF(filterClipp[6], curr, pImg1[+0], pImg2[+0]) );
01238             sum += filterCoeff[7] * ( clipALF(filterClipp[7], curr, pImg1[-1], pImg2[+1]) );
01239             sum += filterCoeff[8] * ( clipALF(filterClipp[8], curr, pImg1[-2], pImg2[+2]) );
01240 
01241             sum += filterCoeff[9] * ( clipALF(filterClipp[9], curr, pImg0[+3], pImg0[-3]) );
01242             sum += filterCoeff[10] * ( clipALF(filterClipp[10], curr, pImg0[+2], pImg0[-2]) );
01243             sum += filterCoeff[11] * ( clipALF(filterClipp[11], curr, pImg0[+1], pImg0[-1]) );
01244           }
01245           else
01246           {
01247             sum += filterCoeff[0] * ( clipALF(filterClipp[0], curr, pImg3[+0], pImg4[+0]) );
01248 
01249             sum += filterCoeff[1] * ( clipALF(filterClipp[1], curr, pImg1[+1], pImg2[-1]) );
01250             sum += filterCoeff[2] * ( clipALF(filterClipp[2], curr, pImg1[+0], pImg2[+0]) );
01251             sum += filterCoeff[3] * ( clipALF(filterClipp[3], curr, pImg1[-1], pImg2[+1]) );
01252 
01253             sum += filterCoeff[4] * ( clipALF(filterClipp[4], curr, pImg0[+2], pImg0[-2]) );
01254             sum += filterCoeff[5] * ( clipALF(filterClipp[5], curr, pImg0[+1], pImg0[-1]) );
01255           }
01256           if (!(isNearVBabove || isNearVBbelow))
01257           {
01258             sum = (sum + offset) >> shift;
01259           }
01260           else
01261           {
01262             sum = (sum + (1 << ((shift + 3) - 1))) >> (shift + 3);
01263           }
01264           sum += curr;
01265           pRec1[jj] = ClipPel( sum, clpRng );
01266 
01267           pImg0++;
01268           pImg1++;
01269           pImg2++;
01270           pImg3++;
01271           pImg4++;
01272           pImg5++;
01273           pImg6++;
01274         }
01275       }
01276     }
01277 
01278     pRec0 += dstStride2;
01279     pRec1 += dstStride2;
01280 
01281     pImgYPad0 += srcStride2;
01282     pImgYPad1 += srcStride2;
01283     pImgYPad2 += srcStride2;
01284     pImgYPad3 += srcStride2;
01285     pImgYPad4 += srcStride2;
01286     pImgYPad5 += srcStride2;
01287     pImgYPad6 += srcStride2;
01288   }
01289 }
01290 
01291 template<AlfFilterType filtTypeCcAlf>
01292 void AdaptiveLoopFilter::filterBlkCcAlf(const PelBuf &dstBuf, const CPelUnitBuf &recSrc, const Area &blkDst,
01293                                         const Area &blkSrc, const ComponentID compId, const int16_t *filterCoeff,
01294                                         const ClpRngs &clpRngs, CodingStructure &cs, int vbCTUHeight, int vbPos)
01295 {
01296   CHECK(1 << floorLog2(vbCTUHeight) != vbCTUHeight, "Not a power of 2");
01297 
01298   CHECK(!isChroma(compId), "Must be chroma");
01299 
01300   const SPS*     sps           = cs.slice->getSPS();
01301   ChromaFormat nChromaFormat   = sps->getChromaFormatIdc();
01302   const int clsSizeY           = 4;
01303   const int clsSizeX           = 4;
01304   const int      startHeight        = blkDst.y;
01305   const int      endHeight          = blkDst.y + blkDst.height;
01306   const int      startWidth         = blkDst.x;
01307   const int      endWidth           = blkDst.x + blkDst.width;
01308   const int scaleX             = getComponentScaleX(compId, nChromaFormat);
01309   const int scaleY             = getComponentScaleY(compId, nChromaFormat);
01310 
01311   CHECK( startHeight % clsSizeY, "Wrong startHeight in filtering" );
01312   CHECK( startWidth % clsSizeX, "Wrong startWidth in filtering" );
01313   CHECK( ( endHeight - startHeight ) % clsSizeY, "Wrong endHeight in filtering" );
01314   CHECK( ( endWidth - startWidth ) % clsSizeX, "Wrong endWidth in filtering" );
01315 
01316   CPelBuf     srcBuf     = recSrc.get(COMPONENT_Y);
01317   const int   lumaStride = srcBuf.stride;
01318   const Pel * lumaPtr    = srcBuf.buf + blkSrc.y * lumaStride + blkSrc.x;
01319 
01320   const int   chromaStride = dstBuf.stride;
01321   Pel *       chromaPtr    = dstBuf.buf + blkDst.y * chromaStride + blkDst.x;
01322 
01323   for( int i = 0; i < endHeight - startHeight; i += clsSizeY )
01324   {
01325     for( int j = 0; j < endWidth - startWidth; j += clsSizeX )
01326     {
01327       for( int ii = 0; ii < clsSizeY; ii++ )
01328       {
01329         int row       = ii;
01330         int col       = j;
01331         Pel *srcSelf  = chromaPtr + col + row * chromaStride;
01332 
01333         int offset1 = lumaStride;
01334         int offset2 = -lumaStride;
01335         int offset3 = 2 * lumaStride;
01336         row <<= scaleY;
01337         col <<= scaleX;
01338         const Pel *srcCross = lumaPtr + col + row * lumaStride;
01339 
01340         int pos = ((startHeight + i + ii) << scaleY) & (vbCTUHeight - 1);
01341         if (scaleY == 0 && (pos == vbPos || pos == vbPos + 1))
01342         {
01343           continue;
01344         }
01345         if (pos == (vbPos - 2) || pos == (vbPos + 1))
01346         {
01347           offset3 = offset1;
01348         }
01349         else if (pos == (vbPos - 1) || pos == vbPos)
01350         {
01351           offset1 = 0;
01352           offset2 = 0;
01353           offset3 = 0;
01354         }
01355 
01356         for (int jj = 0; jj < clsSizeX; jj++)
01357         {
01358           const int jj2     = (jj << scaleX);
01359           const int offset0 = 0;
01360 
01361           int sum = 0;
01362           const Pel currSrcCross = srcCross[offset0 + jj2];
01363           sum += filterCoeff[0] * (srcCross[offset2 + jj2    ] - currSrcCross);
01364           sum += filterCoeff[1] * (srcCross[offset0 + jj2 - 1] - currSrcCross);
01365           sum += filterCoeff[2] * (srcCross[offset0 + jj2 + 1] - currSrcCross);
01366           sum += filterCoeff[3] * (srcCross[offset1 + jj2 - 1] - currSrcCross);
01367           sum += filterCoeff[4] * (srcCross[offset1 + jj2    ] - currSrcCross);
01368           sum += filterCoeff[5] * (srcCross[offset1 + jj2 + 1] - currSrcCross);
01369           sum += filterCoeff[6] * (srcCross[offset3 + jj2    ] - currSrcCross);
01370 
01371           sum = (sum + ((1 << m_scaleBits ) >> 1)) >> m_scaleBits;
01372           const int offset = 1 << clpRngs.comp[compId].bd >> 1;
01373           sum = ClipPel(sum + offset, clpRngs.comp[compId]) - offset;
01374           sum += srcSelf[jj];
01375           srcSelf[jj] = ClipPel(sum, clpRngs.comp[compId]);
01376         }
01377       }
01378     }
01379 
01380     chromaPtr += chromaStride * clsSizeY;
01381 
01382     lumaPtr += lumaStride * clsSizeY << getComponentScaleY(compId, nChromaFormat);
01383   }
01384 }
